import { expect, test } from "bun:test";

import { checkBootstrap, findMissing, normalizeHookNames } from "../src/bootstrap.ts";

test("all hooks installed is ok", () => {
  expect(checkBootstrap({ required: ["pre-commit"], installed: ["pre-commit"] })).toEqual({
    ok: true,
    missing: [],
  });
});

test("a missing hook is reported", () => {
  expect(checkBootstrap({ required: ["pre-commit", "pre-push"], installed: ["pre-commit"] })).toEqual(
    { ok: false, missing: ["pre-push"] },
  );
});

test("empty install set reports everything required", () => {
  expect(checkBootstrap({ required: ["pre-commit"], installed: [] })).toEqual({
    ok: false,
    missing: ["pre-commit"],
  });
});

test("findMissing picks uninstalled descriptors", () => {
  expect(
    findMissing([
      { name: "h-b", installed: true },
      { name: "h-a", installed: false },
    ]),
  ).toEqual(["h-a"]);
});

test("normalize lowercases and dedupes", () => {
  expect(normalizeHookNames(["Pre-Push", "pre-commit", "PRE-PUSH"])).toEqual([
    "pre-commit",
    "pre-push",
  ]);
});
